insert="""
 recordJuryRigMaintenance({campaignId,pcId=null,itemId,hoursSincePrior=0,backlogClearHours=0}){const {loaded,state}=load(this.persistence,campaignId);if(!state)return Object.freeze({status:loaded.status});const {id,pc}=resolvePc(state,pcId);if(!pc)return Object.freeze({status:'CHARACTER_NOT_FOUND_NO_MUTATION',revision:loaded.revision});const item=inventoryItem(pc,itemId);if(!item||item?.crafting?.quality!=='JURY_RIGGED')return Object.freeze({status:'JURY_RIGGED_ITEM_NOT_FOUND_NO_MUTATION',revision:loaded.revision});const craft=pc.skills?.Craft;if(!Number.isInteger(craft)||craft<0)return Object.freeze({status:'CRAFT_0_REQUIRED_NO_MUTATION',revision:loaded.revision});if(!Number.isFinite(hoursSincePrior)||hoursSincePrior<0||!Number.isFinite(backlogClearHours)||backlogClearHours<0)return Object.freeze({status:'INVALID_MAINTENANCE_INTERVAL_NO_MUTATION',revision:loaded.revision});const priorStatus=String(item.crafting?.maintenance?.status??'ACTIVE');if(priorStatus==='ITEM_DISABLED'&&backlogClearHours<1)return Object.freeze({status:'BACKLOG_CLEAR_HOUR_REQUIRED_NO_MUTATION',revision:loaded.revision,requiredHours:1});const next=clone(state),npc=clone(pc),target=inventoryItem(npc,itemId);target.crafting={...(target.crafting??{}),maintenance:{hoursSincePrior,status:hoursSincePrior>=24?'ITEM_DISABLED':'ACTIVE',maintainerId:id,recordedAtRevision:loaded.revision+1}};savePc(next,id,npc);const c=commit({persistence:this.persistence,loaded,next,campaignId,kind:'JURY_RIG_MAINTENANCE_RECORDED',suffix:`jury-maint:${id}:${itemId}`,payload:{pcId:id,itemId,maintenance:target.crafting.maintenance}});return Object.freeze({status:c.receipt.status,receipt:c.receipt,maintenance:target.crafting.maintenance});}
"""
